760|// See
761|// http://stackoverflow.com/questions/6089231/getting-std-ifstream-to-handle-lf-cr-and-crlf
762|static std::istream &safeGetline(std::istream &is, std::string &t) {
763|  t.clear();
764|
765|  // The characters in the stream are read one-by-one using a std::streambuf.
766|  // That is faster than reading them one-by-one using the std::istream.
767|  // Code that uses streambuf this way must be guarded by a sentry object.
768|  // The sentry object performs various tasks,
769|  // such as thread synchronization and updating the stream state.
770|
771|  std::istream::sentry se(is, true);
772|  std::streambuf *sb = is.rdbuf();
773|
774|  if (se) {
775|    for (;;) {
776|      int c = sb->sbumpc();
777|      switch (c) {
778|        case '\n':
779|          return is;
780|        case '\r':
781|          if (sb->sgetc() == '\n') sb->sbumpc();
782|          return is;
783|        case EOF:
784|          // Also handle the case when the last line has no line ending
785|          if (t.empty()) is.setstate(std::ios::eofbit);
786|          return is;
787|        default:
788|          t += static_cast<char>(c);
789|      }
790|    }
791|  }
792|
793|  return is;
